    /**
     * Handles loading a Person using a UUID
     * @param		UUID uuid 
     * @return		Person
     */    
    @GetMapping("/load")
    public Person load( @RequestParam(required=true) UUID uuid ) {    	
    	Person entity = null;

    	try {  
    		entity = service.getPerson( new PersonFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Person using Id " + uuid );
            return null;
        }

        return entity;
    }

